fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"

piece_vals = {'p':100,'n':320,'b':330,'r':500,'q':900,'k':0}

def evaluate(fen):
    # check terminal
    return None  # placeholder

def eval_position(pos):
    if pos.get('game_over'):
        w = pos.get('winner')
        if w == 'white':
            return 100000
        if w == 'black':
            return -100000
        return 0
    f = pos['fen']
    parts = f.split()
    board = parts[0]
    turn = parts[1]
    score = 0
    rows = board.split('/')
    for ri, row in enumerate(rows):
        rank = 8 - ri
        fi = 0
        for ch in row:
            if ch.isdigit():
                fi += int(ch)
                continue
            file_char = 'abcdefgh'[fi]
            square = file_char + str(rank)
            val = piece_vals[ch.lower()]
            if ch.isupper():
                score += val
            else:
                score -= val
            if square in ('d4','e4','d5','e5'):
                if ch.isupper():
                    score += 12
                else:
                    score -= 12
            fi += 1
    # check term
    if 'in_check' in pos and pos['in_check']:
        pass
    # determine check via fen? pos may not have in_check; simulate result does
    if pos.get('in_check'):
        if turn == 'black':
            score += 25
        else:
            score -= 25
    return score

cur = simulate_move(fen)
legal = sorted(cur['legal_moves'])
print("legal:", legal)

best = None
best_score = None
for cand in legal:
    after = simulate_move(fen, cand)
    if after.get('game_over'):
        s = eval_position(after)
        if best_score is None or s > best_score:
            best_score = s; best = cand
        continue
    replies = after['legal_moves']
    worst = None
    for rep in replies:
        r = simulate_move(after['fen'], rep)
        sc = eval_position(r)
        if worst is None or sc < worst:
            worst = sc
    if worst is None:
        worst = eval_position(after)
    if best_score is None or worst > best_score:
        best_score = worst; best = cand

print("best:", best, "score:", best_score)
play_move(best)
